import { Scene, Poly, Color } from "retiam";

export class HexagonScene extends Scene {
    public async run() {
        this.camera.position.set([0, 0, 100]);

        // Regular 6-sided hexagon with radius 30 and rounded corner radius 8
        const hex = Poly.regular(6, 30, {
            cornerRadius: 8,
            fill: new Color(0.1, 0.5, 0.9, 0.7),
            stroke: new Color(1.0, 1.0, 1.0, 1.0),
            stroke_width: 3.0
        });
        this.add(hex);

        this.always(() => {
            hex.transform.rotation.z = this.time * 0.001;
            this.invalidate();
        });
    }
}

import { Scene, Poly, Color } from "retiam";

export class WaveformScene extends Scene {
    public async run() {
        const SAMPLES = 500;
        const rawPoints = new Float32Array(SAMPLES * 2);

        // Initialize Polyline
        const waveform = new Poly([], {
            stroke: new Color(0.2, 1.0, 0.6, 1.0),
            stroke_width: 2.5,
            isClosed: false
        });
        this.add(waveform);

        this.always(() => {
            const time = this.time * 0.003;

            // Stream x, y coordinates directly into the Float32Array:
            for (let i = 0; i < SAMPLES; i++) {
                const x = (i - SAMPLES / 2) * 0.5;
                const y = Math.sin(time + i * 0.05) * 15.0 + Math.sin(time * 2.0 + i * 0.1) * 5.0;
                rawPoints[i * 2 + 0] = x;
                rawPoints[i * 2 + 1] = y;
            }

            // Zero-allocation update to GPU:
            waveform.setRawVertices(rawPoints, false);
            this.invalidate();
        });
    }
}

import { Scene, Poly, Color } from "retiam";

export class LaserScene extends Scene {
    public async run() {
        const starPoints = [
            { x: 0, y: 30 }, { x: 9, y: 9 }, { x: 30, y: 9 },
            { x: 14, y: -4 }, { x: 20, y: -25 }, { x: 0, y: -12 },
            { x: -20, y: -25 }, { x: -14, y: -4 }, { x: -30, y: 9 },
            { x: -9, y: 9 }
        ];

        const star = new Poly(starPoints as any, {
            stroke: new Color(1.0, 0.2, 0.4, 1.0),
            stroke_width: 4.0,
            isClosed: true
        });
        this.add(star);

        // Animate stroke trimming from t1 to t2:
        this.always(() => {
            const t = (this.time * 0.0008) % 2.0;
            star.state.t1 = Math.max(0.0, t - 1.0); // trailing edge
            star.state.t2 = Math.min(1.0, t);       // leading edge
            this.invalidate();
        });
    }
}
